// CONFIDENCE: MEDIUM. Rope geometry update. Raw offsets: WeaponMesh 0x240, OwningProjectileMesh 0x250, RopeMesh 0x218, RopeProjectileMesh 0x220, StartLocation 0x228, EndLocation 0x234.
if (WeaponMesh == nullptr || OwningProjectileMesh == nullptr || RopeMesh == nullptr || RopeProjectileMesh == nullptr) return;
// Socket-name NONE checks in the original (FName_EqualsEName results) are discarded, so they are omitted.
StartLocation = WeaponMesh->GetSocketLocation(WeaponMeshSocketName);          // vslot 0x410 (see AFortHookGunRope__SetStartPointOfRope)
EndLocation   = OwningProjectileMesh->GetSocketLocation(OwningProjectileMeshSocketName);
FVector Dir = EndLocation - StartLocation;
FMatrix M = FRotationMatrix::MakeFromX(Dir);             // FUN_142c55770
FRotator R = M.Rotator();                                 // FUN_142c5ce70 (matrix to rotator)
FQuat Rot  = R.Quaternion();                              // FUN_142c5c060 (rotator to quaternion)
FTransform RopeXf(Rot, StartLocation, FVector(Dir.Size() * 0.01f, 1.0f, 1.0f));   // scale: length in metres along X, cm to m
RopeMesh->SetWorldTransform(RopeXf, false, nullptr, ETeleportType::None);        // FUN_1441250e0 (USceneComponent::SetWorldTransform, MEDIUM)
RopeProjectileMesh->SetWorldLocation(EndLocation, false, nullptr, ETeleportType::None);   // FUN_144124390 (SetWorldLocation)
